// Dashboard logic
const years=[2022, 2023, 2024],  fmt=n=>n==null?'—':new Intl.NumberFormat('en-US').format(n), pct=n=>n==null?'—':(n>=0?'+':'')+n.toFixed(1)+'%';
const ids=['activity', 'occupation', 'sex', 'age', 'country'], els=Object.fromEntries([...ids,'year','current','currentLabel','change','yoy','count','trend','trendNote','bars','search','tbody','csv','colyear'].map(k=>[k,document.getElementById(k)]));
const opts=(id,items,selected)=>{
  els[id].innerHTML='';
  items.forEach(x=>{
    let o=document.createElement('option'); o.value=x; o.textContent=x; els[id].append(o)
  });
  els[id].value=selected
};
const unique=i=>[...new Set(DATA.map(r=>r[i]))].sort((a,b)=>a.localeCompare(b));
const countries=unique(1);
const aggregates=new Set(['Total','FOREIGN COUNTRIES, TOTAL','Foreign countries, total','Europe','Asia','Africa','America','Oceania','Unknown','Other countries','Stateless','Unknown nationality']);
opts('activity',unique(0),'Total');
opts('occupation',unique(2),'Total');
opts('sex',unique(3),'Total');
opts('age',unique(4),'Total');
opts('country',countries,'Finland');
const lookup=new Map(DATA.map(r=>[r.slice(0,5).join('\u001f'),r[5]]));
const get=(a,c,o,s,g)=>lookup.get([a,c,o,s,g].join('\u001f'))||[null, null, null];
const numeric=x=>Number.isFinite(x);
const filter=()=>({
  y:+els.year.value,yi:years.indexOf(+els.year.value),a:els.activity.value,o:els.occupation.value,s:els.sex.value,g:els.age.value,c:els.country.value
});
let exportRows=[];
function render(){
  const f=filter(), chosen=get(f.a,f.c,f.o,f.s,f.g), current=chosen[f.yi], prior=chosen[f.yi-1], base=chosen[0];
  els.current.textContent=fmt(current);
  els.currentLabel.textContent=f.c+' · '+f.y;
  els.change.textContent=numeric(current)&&numeric(base)?fmt(current-base):'—';
  els.yoy.textContent=numeric(current)&&numeric(prior)?pct(prior===0?null:100*(current-prior)/prior):'—';
  els.colyear.textContent=f.y;
let ranking=countries.filter(c=>!aggregates.has(c)).map(c=>{
    let v=get(f.a,c,f.o,f.s,f.g); return {
      c,v:v[f.yi],base:v[0]
    }
  }).filter(r=>numeric(r.v)).sort((a,b)=>b.v-a.v);
  els.count.textContent=fmt(ranking.length);
  exportRows=ranking;
let top=ranking.slice(0,12), max=top[0]?.v||1;
  els.bars.innerHTML=top.map(r=>`<div class="barrow"><span title="${escapeHtml(r.c)}">${escapeHtml(r.c)}</span><div class="track"><div class="fill" style="width:${100*r.v/max}%"></div></div><strong>${fmt(r.v)}</strong></div>`).join('')||'<p class="muted">No data for these filters.</p>';
let available=chosen.map((v,i)=>({
    x:2022+i,v
  })).filter(d=>numeric(d.v));
  if(!available.length){
    els.trend.innerHTML='<p class="muted">No available trend.</p>'
  }else{
    let maxv=Math.max(...available.map(d=>d.v),1), points=chosen.map((v,i)=>numeric(v)?{
      x:65+i*175,y:210-v/maxv*155,v,year:2022+i
    }:null), segments=[];
    for(let i=1; i<points.length; i++)if(points[i-1]&&points[i])segments.push(`<line x1="${points[i-1].x}" y1="${points[i-1].y}" x2="${points[i].x}" y2="${points[i].y}" stroke="#55dfc1" stroke-width="4"/>`);
    els.trend.innerHTML=`<svg viewBox="0 0 480 250" role="img" aria-label="Population trend 2022 to 2024"><line x1="40" y1="210" x2="445" y2="210" stroke="#476273"/>${segments.join('')}${points.map((p,i)=>p?`<circle cx="${p.x}" cy="${p.y}" r="6" fill="#83efcd"/><text x="${p.x}" y="${Math.max(20,p.y-16)}" text-anchor="middle" fill="#eaf8ff" font-size="14">${
      fmt(p.v)
    }</text>`:'').join('')}${years.map((y,i)=>`<text x="${65+i*175}" y="235" text-anchor="middle" fill="#b6d0df" font-size="14">${
      y
    }</text>`).join('')}</svg>`
  }els.trendNote.textContent=f.c+' · '+f.a+' · '+f.o+' · '+f.s+' · '+f.g;
let term=els.search.value.trim().toLocaleLowerCase();
  let found=ranking.filter(r=>r.c.toLocaleLowerCase().includes(term));
  els.tbody.innerHTML=found.map(r=>{
    let d=numeric(r.base)?r.v-r.base:null,p=numeric(r.base)&&r.base!==0?d/r.base*100:null; return `<tr><td><a href="#" data-country="${escapeHtml(r.c)}">${escapeHtml(r.c)}</a></td><td>${fmt(r.v)}</td><td>${fmt(r.base)}</td><td>${d==null?'—':(d>=0?'+':'')+fmt(d)}</td><td>${pct(p)}</td></tr>`
  }).join('')||'<tr><td colspan="5">No matching nationalities.</td></tr>';

}
function escapeHtml(s){
  return s.replace(/[&<>"']/g,c=>({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[c]))
}
ids.concat('year').forEach(k=>els[k].addEventListener('change',render));
els.search.addEventListener('input',render);
els.tbody.addEventListener('click',e=>{
  let a=e.target.closest('a[data-country]'); if(a){
    e.preventDefault(); els.country.value=a.dataset.country; render(); window.scrollTo({
      top:0,behavior:'smooth'
    })
  }
});
els.csv.addEventListener('click',()=>{
  let f=filter(),lines=[['Nationality','Year','Population','Population 2022','Change','Change %'],...exportRows.map(r=>[r.c,f.y,r.v,r.base,numeric(r.base)?r.v-r.base:'',numeric(r.base)&&r.base!==0?((r.v-r.base)/r.base*100).toFixed(1):''])]; let csv=lines.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'); let a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{
    type:'text/csv;charset=utf-8'
  })); a.href=url; a.download='finland_population_nationality_'+f.y+'.csv'; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000)
});
render();
